// Draft v5 folder loader: typed fields live in change.json and authored prose
// lives in proposal.md and design.md under the outline's "## " headings.
// This module reads, splits, and checks the folder (outline order, no TODO
// or TBD, no empty section); renderDraftProposal and renderDraftDesign merge
// the prose with the derived sections. nfr and observability live only in
// change.json and derive grounding v2's sections (one home).

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { OUTLINE, derivedSectionKeys, sectionHeading } from "./validation/outline-contract.mjs";
import { groundingFromQuality } from "./validation/quality-fields.mjs";
import { FOLDER_DRAFT_VERSION } from "./validation/draft-version.mjs";

export const DRAFT_FOLDER_VERSION = FOLDER_DRAFT_VERSION;
export const DRAFT_FOLDER_PROSE = Object.freeze(["proposal", "design"]);

const FENCE = /^ {0,3}(`{3,}|~{3,})/;

function headingIndex(document) {
  const derived = new Set(derivedSectionKeys(document));
  const index = new Map();
  for (const row of OUTLINE[document])
    for (const heading of [row.heading.en, row.heading.th])
      if (!index.has(heading)) index.set(heading, { row, derived: derived.has(row.key) });
  return index;
}

// Splits one markdown file into { key: body } by level-2 headings. A body is
// the exact text between its heading line and the next heading line.
export function splitProse(document, text, { language, file = `${document}.md` } = {}) {
  const index = headingIndex(document);
  const accepted = OUTLINE[document]
    .filter((row) => row.owner === "author")
    .map((row) => sectionHeading(row, language));
  const sections = {};
  const issues = [];
  const seen = new Set();
  const lines = String(text).split(/(?<=\n)/);
  let fence = null;
  let current = null;
  let preamble = "";
  for (const line of lines) {
    const bare = line.replace(/\r?\n$/, "");
    const marker = bare.match(FENCE);
    if (marker) {
      if (!fence) fence = marker[1];
      else if (marker[1][0] === fence[0] && marker[1].length >= fence.length && !bare.slice(bare.indexOf(marker[1]) + marker[1].length).trim())
        fence = null;
    }
    const heading = !fence && !marker && /^## /.test(bare) ? bare.slice(3).trim() : null;
    if (heading === null) {
      if (current) current.body += line;
      else if (!/^# /.test(bare)) preamble += line;
      continue;
    }
    current = null;
    const match = index.get(heading);
    if (!match) {
      issues.push(`${file} heading '${heading}' is not an outline section; accepted headings: ${accepted.join(", ")}`);
    } else if (match.derived) {
      issues.push(`${heading} is generated by the harness; remove it from ${file}`);
    } else if (seen.has(match.row.key)) {
      issues.push(`${file} repeats heading '${heading}'; keep one section per heading`);
    } else {
      seen.add(match.row.key);
      current = { key: match.row.key, heading, body: "" };
      sections[match.row.key] = current;
      continue;
    }
    // Swallow the rejected section's body so it is not mistaken for preamble.
    current = { body: "" };
  }
  if (preamble.trim())
    issues.push(`${file} has text before the first ## heading; move it under an outline heading`);
  issues.push(...orderIssues(document, Object.values(sections), file));
  const prose = {};
  for (const [key, section] of Object.entries(sections)) {
    if (!section.body.trim()) {
      issues.push(`${file} section '${section.heading}' is empty; write it or remove the heading`);
      continue;
    }
    const placeholder = section.body.match(PLACEHOLDER);
    if (placeholder)
      issues.push(`${file} section '${section.heading}' contains ${placeholder[1]}; replace it with the settled content`);
    prose[key] = section.body;
  }
  return { prose, issues };
}

const PLACEHOLDER = /(?<![A-Za-z0-9_])(TODO|TBD)(?![A-Za-z0-9_])/i;

// True when a v5 draft authors the proposal section `key` as prose, so checks
// that look for the typed field also accept the prose that replaces it.
export function hasAuthoredProposalProse(draft, key) {
  const body = draft?.prose?.proposal?.[key];
  return typeof body === "string" && body.trim() !== "";
}

// Authored headings must follow the outline's reader order.
function orderIssues(document, sections, file) {
  const rank = new Map(OUTLINE[document].map((row, index) => [row.key, index]));
  const issues = [];
  let latest = null;
  for (const section of sections) {
    if (latest && rank.get(section.key) < rank.get(latest.key))
      issues.push(`${file}: '${latest.heading}' must come after '${section.heading}'`);
    else latest = section;
  }
  if (!issues.length) return [];
  const order = [...sections].sort((a, b) => rank.get(a.key) - rank.get(b.key))
    .map((section) => section.heading).join(", ");
  return issues.map((issue) => `${issue}; outline order is ${order}`);
}

// A v5 draft keeps nfr and observability only in change.json; grounding v2's
// nfrAssessment and observability are derived from them and replace what the
// draft's grounding v2 held. A draft without grounding v2 (none, or the
// decisions-only v3) gains none: a partial ledger would fail validation.
export function withQualityGrounding(draft) {
  if (draft?.version !== DRAFT_FOLDER_VERSION || draft.grounding?.version !== 2) return draft;
  const nfr = Array.isArray(draft.nfr) && draft.nfr.length > 0;
  const observability = draft.observability !== undefined && draft.observability !== null;
  if (!nfr && !observability) return draft;
  const derived = groundingFromQuality(draft);
  return {
    ...draft,
    grounding: {
      ...draft.grounding,
      ...(nfr ? { nfrAssessment: derived.nfrAssessment } : {}),
      ...(observability ? { observability: derived.observability } : {})
    }
  };
}

export function loadDraftFolder(dir, { name = dir } = {}) {
  const issues = [];
  const jsonPath = join(dir, "change.json");
  let draft = null;
  if (!existsSync(jsonPath)) {
    issues.push(`draft folder ${name} is missing change.json`);
  } else {
    try {
      draft = JSON.parse(readFileSync(jsonPath, "utf8"));
    } catch (error) {
      issues.push(`${name}/change.json is not valid JSON: ${error.message}`);
    }
    if (draft !== null && (typeof draft !== "object" || Array.isArray(draft))) {
      issues.push(`${name}/change.json must be a JSON object`);
      draft = null;
    } else if (draft && draft.version !== DRAFT_FOLDER_VERSION) {
      issues.push(`${name}/change.json must declare version ${DRAFT_FOLDER_VERSION}`);
    }
  }
  const language = draft?.language;
  const prose = {};
  for (const document of DRAFT_FOLDER_PROSE) {
    const path = join(dir, `${document}.md`);
    if (!existsSync(path)) { prose[document] = {}; continue; }
    const split = splitProse(document, readFileSync(path, "utf8"), { language, file: `${document}.md` });
    prose[document] = split.prose;
    issues.push(...split.issues);
  }
  return { draft: draft ? withQualityGrounding({ ...draft, prose }) : null, issues };
}
